  const step = Math.max(1, Math.ceil(sorted.length / sample))
  const created = []
  for (const [index, { name, file }] of sorted.entries()) {
    if (index % step !== 0 || !/^[A-Z]\w*(\.[A-Z]\w*)?$/.test(name) || !/\.(tsx?)$/.test(file)) continue
