    const [root] = name.split('.')
    const escaped = escapeRegExp(root)
    const named =
      new RegExp(`export\\s+(?:declare\\s+)?(?:const|function|class)\\s+${escaped}\\b`).test(source) ||
      new RegExp(`export\\s*\\{[^}]*\\b${escaped}\\b[^}]*\\}`).test(source)
