// usage: node measure.mjs <repoRoot> <corporaDir> <corpus>
import { resolve, join } from 'node:path'
import { pathToFileURL } from 'node:url'
const [repo, corpora, corpus] = process.argv.slice(2)
const CORPORA = {
  mantine: ['mantine', ['packages/@mantine/core/src']],
  chakra: ['chakra-ui', ['packages/react/src']],
  shadcn: ['shadcn-ui', ['apps/v4']],
  antd: ['ant-design', ['components']],
  spectrum: ['react-spectrum', ['packages', 'starters']],
}
const [root, src] = CORPORA[corpus]
const rootDir = resolve(corpora, root)
process.chdir(rootDir)
const dist = join(repo, 'packages/storybook/dist')
const { DocgenSession } = await import(pathToFileURL(join(dist, 'session.js')).href)
const napi = await import(pathToFileURL(join(repo, 'packages/napi/index.js')).href)
const session = new DocgenSession({ srcDirs: src.map((d) => resolve(rootDir, d)), loadDependencies: true, collapseInheritedProps: 'none' }, napi.default ?? napi)
const t = performance.now()
await session.fresh()
const initMs = performance.now() - t
const keys = [...session.components.keys()]
const out = { corpus, components: keys.length, initMs: Math.round(initMs), today: 0, withOpaqueInfo: 0, alsoFallback: 0, codes: {}, onlyCodes: {}, examples: [], msgShapes: {} }
const napiBinding = napi.default ?? napi
const t2 = performance.now()
for (const key of keys) {
  const { doc } = await session.documentation(key)
  if (!doc) continue
  const raw = JSON.parse(napiBinding.sessionComponentAnswers(session.sessionId, [key]))[key]
  if (!raw) continue
  const d = raw.diagnostics
  const today = d.some((x) => x.severity !== 'info')
  const infoCodes = [...new Set(d.filter((x) => x.severity === 'info' && (x.code === 'OPAQUE_TYPE' || x.code === 'INDEXED_ACCESS_OPAQUE')).map((x) => x.code))]
  if (today) out.today++
  if (infoCodes.length) {
    out.withOpaqueInfo++
    for (const c of infoCodes) out.codes[c] = (out.codes[c] ?? 0) + 1
    if (!today) {
      out.alsoFallback++
      for (const c of infoCodes) out.onlyCodes[c] = (out.onlyCodes[c] ?? 0) + 1
      for (const x of d.filter((x) => x.severity === 'info' && infoCodes.includes(x.code))) {
        const shape = x.message.replaceAll(/'[^']*'/g, "'_'").replaceAll(/\/\S+/g, '<path>')
        out.msgShapes[shape] = (out.msgShapes[shape] ?? 0) + 1
        if (out.examples.length < 15) out.examples.push(`${session.components.get(key).displayName}: ${x.message}`)
      }
    }
  }
}
out.docgenMs = Math.round(performance.now() - t2)
out.answered = out.components - out.today
out.pctToday = +(out.today / out.components * 100).toFixed(1)
out.pctAlso = +(out.alsoFallback / out.components * 100).toFixed(1)
out.pctTotal = +((out.today + out.alsoFallback) / out.components * 100).toFixed(1)
console.log(JSON.stringify(out, null, 1))
EOF
